or_comparado }}</td><td class="{{ $c->diferencia>0?'text-success':($c->diferencia<0?'text-danger':'') }}">{{ $c->diferencia }} @if($c->variacion_porcentual!==null)({{ $c->variacion_porcentual }}%)@endif</td></tr>@endforeach</tbody></table>@endif</x-card><x-card title="Historial del cliente" class="mt-4"><ul class="list-group list-group-flush">@foreach($historial as $h)<li class="list-group-item px-0"><a href="{{ route('evaluaciones.show',$h->id) }}">{{ \Illuminate\Support\Carbon::parse($h->evaluada_at)->format('d/m/Y H:i') }}</a><div class="small text-muted">{{ $h->evaluador }} · {{ $h->medidas }} medidas</div></li>@endforeach</ul></x-card></div></div>@endsection
